// 4.3.1.2 - Message-payload parse Code node
// Validates a shared-secret header (configure the SAME value in n8n env var
// WAHA_WEBHOOK_SECRET and in Waha's webhook config as a custom header),
// then parses/normalizes the Waha event payload.
//
// NOTE: Waha's webhook config does not have a built-in HMAC signature scheme
// documented in the source material (unlike Documenso/Cal.com/payment webhooks
// in Phase 3.0). A shared-secret header is used here as the minimum viable
// auth check. If Nivy confirms Waha supports HMAC signing on this Waha version,
// upgrade this to the same verify-signature pattern as 3.0.1.3/3.0.1.4 — flagged
// here rather than invented.

const item = $input.item.json;
const body = item.body || item;
const headers = item.headers || {};

const expectedSecret = $env.WAHA_WEBHOOK_SECRET || '';
const providedSecret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '';
// If no secret is configured yet, auth check is skipped (open) — this must be
// closed before go-live, same category as the other unauthenticated webhooks
// already flagged in §10A.5 of the master tracker.
const isAuthValid = expectedSecret !== '' ? providedSecret === expectedSecret : true;

// Expected Waha payload shape (session webhook, event-based):
// { event: "message", session: "default", payload: { id, timestamp, from, fromMe, body, ... } }
const event = body.event || null;
const payload = body.payload || {};

const fromMe = payload.fromMe === true;
const rawFrom = payload.from || payload.chatId || '';
const digitsOnly = String(rawFrom).replace(/[^0-9]/g, '');
const normalizedPhone = digitsOnly ? ('+' + digitsOnly) : null;

const messageText = (payload.body || payload.text || '').toString().slice(0, 2000);
const waMessageId = payload.id || null;
const messageTimestamp = payload.timestamp
  ? new Date(Number(payload.timestamp) * 1000).toISOString()
  : new Date().toISOString();

const isMessageEvent = event === 'message' || event === 'message.any';
const isInboundReply = Boolean(isMessageEvent && fromMe === false && normalizedPhone);

return [{
  json: {
    isAuthValid,
    event,
    fromMe,
    normalizedPhone,
    messageText,
    waMessageId,
    messageTimestamp,
    isInboundReply
  }
}];

// Normalizes the 'found vs not found' shape from the Postgres node above into
// an explicit boolean, since a 0-row SELECT + alwaysOutputData just re-emits
// the input item (no 'id' field) rather than an item with id=null.
const j = $input.item.json;
return [{
  json: {
    ...j,
    clientFound: Boolean(j.id),
    clientId: j.id || null
  }
}];

// Postgres update failed after a match was found. No retry/alert queue exists
// yet for this module (same known-gap pattern as Modules 1.1/1.3/2.3 — see
// master tracker §10A.3). Logged to n8n's own execution log via this node so
// it's at least visible in Executions, not silently lost.
const j = $input.item.json;
return [{ json: { ...j, updateFailed: true } }];

// Inbound message from a phone number not found in clients_master — could be
// a wrong number, a non-lead contact, or a lead whose phone was stored in a
// different format. No action taken beyond logging; matches this module's
// stated scope (reply tracking for known leads/clients only).
const j = $input.item.json;
return [{ json: { ...j, unmatchedPhone: j.normalizedPhone } }];
